using Godot;
using System;
using System.Collections.Generic;
using Settings=Godot.Collections.Dictionary;
public partial class TimelineCanvasOperations
{
    public void draw_video_frames(Control owner,int index,Rect2 rect,Rect2 visible)
    {
        var clip=Clips(owner)[index].As<Resource>();var state=owner.Get("_preview_states").AsGodotDictionary().GetValueOrDefault(clip.Get("id"),new Settings()).AsGodotDictionary();double offset=state.GetValueOrDefault("offset",clip.Get("source_offset")).AsDouble();string path=Actors(owner)[index].As<Resource>().Get("values").AsGodotDictionary().GetValueOrDefault("video","").AsString();var strip=new Rect2(visible.Position+new Vector2(2,2),visible.Size-new Vector2(4,4));if(!strip.HasArea())return;float width=Math.Max(36,strip.Size.Y*16/9);var video=GD.Load<CSharpScript>("res://scripts/actors/core/ActorVideo.cs");for(float x=strip.Position.X;x<strip.End.X;x+=width){double time=offset+(x-rect.Position.X)/N(owner,"pixels_per_second")*clip.Get("playback_speed").AsDouble();var texture=video.Call("frame",path,time,false).As<Texture2D>();var tile=new Rect2(x,strip.Position.Y,Math.Min(width-1,strip.End.X-x),strip.Size.Y);if(texture!=null)owner.DrawTextureRect(texture,tile,false,new Color(1,1,1,.65f));}owner.DrawRect(strip,new Color(.02f,.06f,.06f,.3f));
    }
    public void draw_waveform(Control owner,int index,Rect2 rect,Rect2 visible)
    {
        var editor=owner.GetTree().GetFirstNodeInGroup("actor_timeline_editors");if(editor==null)return;var system=editor.Get("audio_system").AsGodotObject();if(system==null)return;var actor=Actors(owner)[index].As<Resource>();var stream=GD.Load<CSharpScript>("res://scripts/actors/core/ActorAudio.cs").Call("source",actor.Get("values").AsGodotDictionary().GetValueOrDefault("audio","")).As<AudioStream>();if(stream==null)return;var wave=system.Call("waveform",stream).AsFloat32Array();if(wave.Length==0){owner.QueueRedraw();return;}var clip=Clips(owner)[index].As<Resource>();double offset=owner.Get("_preview_states").AsGodotDictionary().GetValueOrDefault(clip.Get("id"),new Settings()).AsGodotDictionary().GetValueOrDefault("offset",clip.Get("source_offset")).AsDouble();float center=visible.Position.Y+visible.Size.Y*.7f,amplitude=visible.Size.Y*.26f;double length=stream.GetLength();if(length<=0)return;for(int x=(int)visible.Position.X+2;x<(int)visible.End.X-2;x+=2){double time=offset+(x-rect.Position.X)/N(owner,"pixels_per_second")*clip.Get("playback_speed").AsDouble();int bin=Math.Clamp((int)(time/length*wave.Length),0,wave.Length-1);float height=Math.Max(.5f,wave[bin]*amplitude);owner.DrawLine(new Vector2(x,center-height),new Vector2(x,center+height),new Color(.56f,.95f,.82f,.55f));}
    }
    public void draw_media_preview(Control owner,Settings state,bool recording)
    {
        var rect=new Rect2((float)(LabelWidth+(state["start"].AsDouble()-N(owner,"scroll_time"))*N(owner,"pixels_per_second")),(float)(Header+state["layer"].AsInt32()*N(owner,"row_height")-N(owner,"scroll_rows")+4),(float)Math.Max(2,state["duration"].AsDouble()*N(owner,"pixels_per_second")),(float)Math.Max(4,N(owner,"row_height")-8));var area=rect.Intersection(new Rect2(LabelWidth,Header,Math.Max(0,owner.Size.X-LabelWidth),Math.Max(0,owner.Size.Y-Header)));if(!area.HasArea())return;var tint=new Color(recording?"ff8291":"92f1cf");var fill=tint;fill.A=.16f;owner.DrawRect(area,fill);owner.DrawRect(area,tint,false,1.5f);var peaks=recording?owner.Get("recording_peaks").AsFloat32Array():Array.Empty<float>();double total=state["duration"].AsDouble();if(!recording&&state["actor"].As<Resource>().Get("type_id").AsString()=="audio"){var editor=owner.GetTree().GetFirstNodeInGroup("actor_timeline_editors");if(editor!=null){var stream=GD.Load<CSharpScript>("res://scripts/actors/core/ActorAudio.cs").Call("source",state["actor"].As<Resource>().Get("values").AsGodotDictionary()["audio"]);peaks=editor.Get("audio_system").AsGodotObject().Call("waveform",stream).AsFloat32Array();}}if(peaks.Length>0&&total>0)for(int x=(int)area.Position.X+1;x<(int)area.End.X;x+=2){int bin=Math.Clamp((int)((x-rect.Position.X)/rect.Size.X*peaks.Length),0,peaks.Length-1);float center=rect.Position.Y+rect.Size.Y*.7f,height=Math.Max(.5f,peaks[bin]*rect.Size.Y*.24f);owner.DrawLine(new Vector2(x,center-height),new Vector2(x,center+height),tint);}if(area.Size.Y>=20&&area.Size.X>=45)owner.DrawString(ThemeDB.FallbackFont,area.Position+new Vector2(8,16),recording?"● Recording":state["path"].AsString().GetFile(),HorizontalAlignment.Left,area.Size.X-12,11,tint);
    }
}
